class Antrean {
  nomor = 0;
  dilayani = [];
  ambil(nama) {
    this.nomor++;
    this.dilayani.push(`${this.nomor}. ${nama}`);
  }
}
const loket = new Antrean();
loket.ambil("Rina");
loket.ambil("Budi");
const loket2 = new Antrean();
console.log(loket.dilayani.join(", "));
console.log(loket2.nomor);

