cards.solution:
class Playlist {
  lagu = [];
  durasi = 0;
  tambah(judul, menit) {
    this.lagu.push(judul);
    this.durasi += menit;
  }
  info() {
    return `${this.lagu.length} lagu, ${this.durasi} menit`;
  }
}
const p = new Playlist();
p.tambah("Bento", 4);
p.tambah("Kangen", 5);
console.log(p.info());
